76	func preflightFragments(t *testing.T) []string {
77		t.Helper()
78		seen := map[string]bool{}
79		for file, funcs := range preflightFunctions {
80			parsed, err := parser.ParseFile(token.NewFileSet(), file, nil, 0)
81			if err != nil {
82				t.Fatal(err)
83			}
84			for _, decl := range parsed.Decls {
85				fn, ok := decl.(*ast.FuncDecl)
86				if !ok {
87					continue
88				}
89				named := false
90				for _, name := range funcs {
91					named = named || fn.Name.Name == name
92				}
93				if !named {
94					continue
95				}
96				ast.Inspect(fn.Body, func(node ast.Node) bool {
97					if lit, ok := node.(*ast.BasicLit); ok && lit.Kind == token.STRING {
98						if value, err := strconv.Unquote(lit.Value); err == nil && len(strings.TrimSpace(value)) >= 14 {
99							seen[strings.TrimSpace(value)] = true
100						}
101					}
102					return true
103				})
104			}
105		}
106		out := make([]string, 0, len(seen))
107		for fragment := range seen {
108			out = append(out, fragment)
109		}
110		sort.Strings(out)
111		if len(out) < 30 {
112			t.Fatalf("read only %d message fragments from the preflight: the extraction lost them", len(out))
113		}
114		return out
115	}
