79		if err != nil {
80			t.Skipf("no delegation policy at the repository root: %v", err)
81		}
82		var policy struct {
83			Agents map[string]struct {
84				Commands map[string][]string `json:"commands"`
85				Resume   struct {
86					Command  []string            `json:"command"`
87					Commands map[string][]string `json:"commands"`
88				} `json:"resume"`
89			} `json:"agents"`
90		}
91		if err := json.Unmarshal(raw, &policy); err != nil {
92			t.Fatal(err)
