94		agent, ok := policy.Agents["claude-opus-5-5"]
95		if !ok {
96			t.Skip("no Claude reviewer profile")
97		}
98		commands := [][]string{agent.Commands["read"], agent.Resume.Command, agent.Resume.Commands["read"]}
99		// An allow-list matches a prefix, so a verb that takes a flag that writes a file or runs a program
100		// (`git log --output`, `go test -exec -c -o`, `go vet -vettool`, `pose lint-spec --json-out`) cannot be
101		// allowed at all: only verbs without such a flag are.
102		writers := []string{"assess", "validate", "--seal", "attest", "record", "apply", "close ", "start", "index", "git commit", "git push", "git add", "git checkout", "git reset", "go build", "go install", "go test", "go vet", "git log", "git diff", "git show", "lint-spec", "rm ", "touch"}
103		for i, command := range commands {
104			var allowed string
105			for j, arg := range command {
106				if arg == "--allowedTools" && j+1 < len(command) {
107					allowed = command[j+1]
108				}
109			}
110			if allowed == "" {
111				t.Fatalf("command %d of the Claude reviewer allows no command: it cannot reproduce what it judges", i)
112			}
113			for _, want := range []string{"Bash(git status:*)", "Bash(pose artifact-check:*)", "Bash(pose surface-check:*)", "Bash(pose review-check:*)", "Bash(pose closeout-check:*)"} {
114				if !strings.Contains(allowed, want) {
115					t.Errorf("command %d does not allow %s", i, want)
116				}
117			}
118			for _, verb := range writers {
119				if strings.Contains(allowed, verb) {
120					t.Errorf("command %d allows %q, a verb that writes", i, verb)
121				}
122			}
